SELECT id, store_id, product_id, quantity, MAX(quantity) OVER (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_quantity, SUM(quantity) OVER (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_quantity, MIN(quantity) OVER (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_quantity, AVG(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS quantity_avg_2 FROM inventory;
